def _collegamenti_in_qualifiche(apps, schema_editor):
    """Le attrezzature già collegate a un processo diventano macchine «Da qualificare»."""
    Asset = apps.get_model("assets", "Asset")
    QualificaMacchina = apps.get_model("anagrafica", "QualificaMacchina")
    through = Asset.processi_qualificati.through
    esistenti = set(QualificaMacchina.objects.values_list("processo_id", "asset_id"))
    nuove = []
    for asset_id, processo_id in through.objects.values_list("asset_id", "processoqualificato_id"):
        if (processo_id, asset_id) in esistenti:
            continue
        esistenti.add((processo_id, asset_id))
        nuove.append(QualificaMacchina(
            processo_id=processo_id, asset_id=asset_id, stato="DA_QUALIFICARE",
            motivo_stato="Collegata prima delle macchine qualificate: registrare la qualifica.",
        ))
    QualificaMacchina.objects.bulk_create(nuove, batch_size=200)


